// Zoom webhook signature verification + URL validation challenge.
// Docs: https://developers.zoom.us/docs/api/webhooks/#verify-webhook-events
const crypto = require('crypto');

const MAX_SKEW_SEC = 300; // replay protection window
const secret = $env.ZOOM_WEBHOOK_SECRET_TOKEN;
const { headers, body } = $input.first().json;

const hmac = (msg) => crypto.createHmac('sha256', secret).update(msg).digest('hex');
const safeEqual = (a, b) =>
  a.length === b.length && crypto.timingSafeEqual(Buffer.from(a), Buffer.from(b));

const ts = headers['x-zm-request-timestamp'] ?? '';
const signature = headers['x-zm-signature'] ?? '';
// Zoom signs compact JSON; re-serialization matches Zoom's reference implementation.
const expected = `v0=${hmac(`v0:${ts}:${JSON.stringify(body)}`)}`;
const isFresh = Math.abs(Date.now() / 1000 - Number(ts)) <= MAX_SKEW_SEC;
const isValid = Boolean(secret) && isFresh && safeEqual(signature, expected);

const event = body?.event ?? 'unknown';
let route, response;

if (!isValid) {
  route = 'invalid';
  response = { status: 401, body: { error: 'invalid signature' } };
} else if (event === 'endpoint.url_validation') {
  const plainToken = body.payload.plainToken;
  route = 'url_validation';
  response = { status: 200, body: { plainToken, encryptedToken: hmac(plainToken) } };
} else if (event === 'recording.completed') {
  route = 'recording.completed';
  response = { status: 200, body: { status: 'accepted' } };
} else {
  route = 'ignored';
  response = { status: 200, body: { status: 'ignored', event } };
}

return [{ json: { route, event, event_ts: body?.event_ts ?? null, response } }];

// Map Zoom recording.completed payload -> internal CallRecording contract.
const { body } = $('Zoom Webhook').first().json;
const rec = body.payload.object;
const files = (rec.recording_files ?? []).filter((f) => f.status === 'completed');

// Prefer audio-only track (smaller, Whisper-friendly), fall back to M4A/MP4.
const audio =
  files.find((f) => f.recording_type === 'audio_only') ??
  files.find((f) => f.file_type === 'M4A') ??
  files.find((f) => f.file_type === 'MP4');

if (!audio) {
  throw new Error(`No downloadable audio in recording ${rec.uuid}`);
}

return [{
  json: {
    idempotency_key: `${rec.uuid}:${audio.id}`,
    source: 'zoom',
    meeting: {
      uuid: rec.uuid,
      id: rec.id,
      topic: rec.topic,
      host_email: rec.host_email,
      start_time: rec.start_time,
      duration_min: rec.duration,
    },
    audio: {
      file_id: audio.id,
      file_type: audio.file_type,
      file_extension: (audio.file_extension ?? audio.file_type).toLowerCase(),
      file_size: audio.file_size,
      download_url: audio.download_url,
      download_token: body.download_token ?? null,
    },
    received_at: new Date().toISOString(),
  },
}];

textOptions.schema:
{
  "type": "object",
  "additionalProperties": false,
  "required": ["summary", "participants", "key_points", "action_items"],
  "properties": {
    "summary": {
      "type": "string",
      "description": "3-5 sentence summary of the call"
    },
    "participants": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["name", "role"],
        "properties": {
          "name": { "type": "string", "description": "Name as mentioned, or 'Speaker 1', 'Speaker 2'…" },
          "role": { "type": ["string", "null"], "description": "Role/company if stated, else null" }
        }
      }
    },
    "key_points": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Main topics, facts, decisions"
    },
    "action_items": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["task", "owner", "due"],
        "properties": {
          "task": { "type": "string" },
          "owner": { "type": ["string", "null"], "description": "Who is responsible, if stated" },
          "due": { "type": ["string", "null"], "description": "Deadline as stated, if any" }
        }
      }
    }
  }
}
